const fs = require('fs');

function randomDate() {
  const start = new Date('2026-06-15');
  const end = new Date('2026-06-29');
  return new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime())).toISOString().split('T')[0];
}

function randomViews() {
  return Math.floor(Math.random() * (150000 - 5000) + 5000);
}

function buildTool(base, idx) {
  const id = base.id;
  const name = base.name;
  const logo = `https://api.dicebear.com/7.x/shapes/svg?seed=${id}`;
  const screenshots = [`https://picsum.photos/seed/${id}1/800/500`, `https://picsum.photos/seed/${id}2/800/500`];
  const seoTitle = `${name} - ${base.shortDesc} | AI Navigator Pro`;
  const seoDescription = base.seoDescription || base.description.slice(0, 75) + "...";
  const featured = idx < 5;
  const trending = idx < 10;
  const views = randomViews();
  const updatedAt = randomDate();
  return {
    id, name, logo, description: base.description, url: base.url,
    price: base.price, isFree: base.isFree, tags: base.tags,
    category: base.category, rating: base.rating, updatedAt,
    screenshots, features: base.features, competitors: base.competitors,
    useCases: base.useCases, seoTitle, seoDescription,
    featured, trending, views
  };
}

